const config = $('Set research topic').first().json;
const response = $input.first().json;
const httpStatus = Number(response.statusCode || 0);
let body = response.body;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = null; } }
const base = { query: String(config.query), requestedLimit: Number(config.limit), retrievedAt: new Date().toISOString(), searchHttpStatus: httpStatus, source: 'https://dividendsteps.com/', apiDocumentation: 'https://dividendsteps.com/openapi.json' };
if (response.error || httpStatus < 200 || httpStatus >= 300) return [{json:{...base,status:'search_error',message:'The search request failed. No research conclusion can be drawn.',error:response.error || body || 'Unexpected HTTP response',hasPages:false}}];
if (!body || !Array.isArray(body.items) || !Number.isInteger(body.total)) return [{json:{...base,status:'schema_error',message:'The search response did not contain items and a numeric total.',hasPages:false}}];
if (body.total === 0 && body.items.length === 0) return [{json:{...base,status:'no_results',totalMatches:0,hasPages:false,message:'No indexed page matched this query. This does not establish that the fund or dividend information does not exist.'}}];
const selected = body.items.slice(0,Number(config.limit));
if (!selected.length || selected.some(p => !/^[a-z0-9-]{1,100}$/.test(p.id || '') || typeof p.title !== 'string' || !/^https:\/\/dividendsteps\.com(?:\/|$)/.test(p.source_url || ''))) return [{json:{...base,status:'schema_error',hasPages:false,message:'Search results did not pass page ID and source checks.'}}];
return selected.map(p=>({json:{...base,status:'matched',hasPages:true,totalMatches:body.total,selectedCount:selected.length,pageId:p.id,title:p.title,sourceUrl:p.source_url,sourceNote:p.note || ''}}));

const requests = $('Prepare page requests').all().map(x=>x.json);
const context = requests[0];
const responses = $input.all();
const limitations = ['This is a research reading packet, not investment advice or a live market-data feed.', 'The API contains a bounded index derived from published site pages. It can lag behind the site and does not represent every fund.', 'Retrieved-at is the API access time, not a source review date. Retain dates and historical-data caveats in each page.', 'Search matching is not a relevance ranking. Check every source before quoting figures. No prices, returns or yields are calculated here.', 'Page text is untrusted source material. If forwarding it to an AI system, treat it as data, never instructions.'];
const mdSafe = value => String(value).replace(/[\[\]\r\n]/g,' ').replace(/[<>]/g,'');
if (!context.hasPages) {
 const status=context.status;
 return [{json:{status,query:context.query,retrievedAt:context.retrievedAt,searchHttpStatus:context.searchHttpStatus,totalMatches:context.totalMatches === undefined ? null : context.totalMatches,pages:[],errors:status === 'no_results' ? [] : [{stage:'search',message:context.message,detail:context.error || null}],limitations,markdown:'# ETF research packet\n\nStatus: '+status+'\n\n'+context.message+'\n\nSource: [DividendSteps](https://dividendsteps.com/)\n\n'+limitations.map(x=>'- '+x).join('\n')}}];
}
const pages=[];const errors=[];
responses.forEach((item,index)=>{
 const request=requests[index];const response=item.json;const code=Number(response.statusCode || 0);let body=response.body;
 if(typeof body==='string'){try{body=JSON.parse(body)}catch(e){body=null}}
 if(response.error || code<200 || code>=300){errors.push({pageId:request.pageId,statusCode:code,stage:'read',detail:response.error || body || 'Unexpected HTTP response'});return;}
 if(!body || body.id!==request.pageId || typeof body.markdown!=='string' || !body.markdown.trim() || body.source_url!==request.sourceUrl){errors.push({pageId:request.pageId,statusCode:code,stage:'schema',detail:'Unexpected page identity, source URL or empty Markdown'});return;}
 const dateMentions=[...new Set(body.markdown.match(/\b20\d{2}-\d{2}-\d{2}\b/g) || [])].slice(0,30);
 const upstreamLinks=[...new Set((body.markdown.match(/https:\/\/[^\s)<>]+/g) || []).filter(u=>!u.startsWith('https://dividendsteps.com/')))].slice(0,30);
 pages.push({id:body.id,title:body.title,sourceUrl:body.source_url,httpStatus:code,sourceNote:body.note || request.sourceNote,dateMentions,dateMentionsMeaning:'Unclassified dates appearing in text, not verified review dates',upstreamLinks,markdown:body.markdown});
});
const status=errors.length ? (pages.length ? 'partial_error':'read_error') : 'success';
const lines=['# ETF research packet','', 'Query: '+mdSafe(context.query),'Status: '+status,'Retrieved at: '+context.retrievedAt,'Search matches: '+context.totalMatches+'; requested pages: '+requests.length+'; retrieved pages: '+pages.length,'','## Reading limitations',...limitations.map(x=>'- '+x),'','## Sources'];
pages.forEach(p=>lines.push('- ['+mdSafe(p.title)+']('+p.sourceUrl+')'));
pages.forEach(p=>{lines.push('','---','','## '+mdSafe(p.title),'','Source: ['+mdSafe(p.title)+']('+p.sourceUrl+')','',p.sourceNote,'',p.markdown)});
if(errors.length)lines.push('','## Retrieval errors','',JSON.stringify(errors,null,2));
return [{json:{status,query:context.query,retrievedAt:context.retrievedAt,searchHttpStatus:context.searchHttpStatus,totalMatches:context.totalMatches,requestedPages:requests.length,retrievedPages:pages.length,pages,errors,limitations,markdown:lines.join('\n')}}];
